function nav(){return `<header class="topbar"><div class="wrap"><a class="brand" href="index.html"><span class="brandmark">M</span><span>THE MAKERS</span></a><button class="hamb" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="site-nav">☰</button><nav class="nav" id="site-nav">${navLinks.map(x=>`<a href="${x[0]}">${x[1]}</a>`).join('')}</nav></div></header>`}
function foot(){return `<footer class="footer"><div class="wrap"><div><strong>The Makers</strong><div class="small">Fantasy football, since 2003.</div></div><div class="small">Updated: ${e(Y.lastUpdated)} · Bad decisions, keeper math, real grudges.</div></div></footer>`}
function hero(t,c='',ey='THE MAKERS · SINCE 2003'){return `<section class="pagehead"><div class="wrap"><div class="eyebrow">${e(ey)}</div><h1>${e(t)}</h1><p>${e(c)}</p></div></section>`}
