  const finals=games.filter(m=>actualForWeekPair(week,m[0],m[1])).length,phase=finals===games.length?'RECAP':'PREVIEW';
  const cards=games.map(m=>{const [a,b]=m,actual=actualForWeekPair(week,a,b),fc=forecastFor(week,a,b),h=E.matchupHistory?E.matchupHistory(a,b):null,customEntry=custom.get(pairId(a,b));let copy=actual?customEntry?.recap:customEntry?.preview;
    if(!copy&&actual)copy=`${actual.winner} won ${scoreText(actual.scoreA,actual.scoreB)}. The result is now part of the 2026 rivalry ledger.`;
    if(!copy)copy=h?.total?`${a} vs ${b}. ${h.rivalry||'The rivalry file is open'} with another regular-season meeting on the schedule.`:`${a} vs ${b}. A fresh Week ${week} matchup with the season still waiting to write the receipt.`;
    const receipt=actual?`<div class="weekly-breakdown-score actual"><small>ACTUAL</small><b>${scoreText(actual.scoreA,actual.scoreB)}</b></div>`:projectionReceipt(fc),isGotw=gotw&&pairId(a,b)===pairId(gotw[0],gotw[1]);
    return `<article class="weekly-breakdown-card${isGotw?' game-of-week-tile':''}">${isGotw?'<div class="gotw-ribbon">GAME OF THE WEEK</div>':''}<div class="weekly-breakdown-head"><span>${e(a)}</span><b>VS</b><span>${e(b)}</span></div>${receipt}<p>${e(copy)}</p></article>`}).join('');
  return `<section class="section weekly-breakdowns"><div class="wrap"><div class="section-head"><div><div class="kicker">EVERY MATCHUP</div><h2>Week ${week} ${phase.toLowerCase()}</h2></div></div><div class="weekly-breakdown-grid">${cards}</div></div></section>`;
