function previewFor(w,a,b){let arr=(D.weeklyPreview||{})[String(w)]||[];return arr.find(x=>(x.a===a&&x.b===b)||(x.a===b&&x.b===a))}
function week(){
  let w=Number(Q.get('week')||1),d=Y.weekly[String(w)]||{};let aw=(d.awards||[]).length?d.awards.map(a=>card(a[1],e(a[2]||''),a[0])).join(''):card('Awards pending','The week has to earn them first.','WEEKLY HARDWARE');let write=d.writeup?`<div class="writeup-copy">${paras(d.writeup)}</div>`:`<div class="empty-state"><b>Write-up pending.</b><br>The recap lands here after the week is played.</div>`;
  if(w>=15){return hero(`Week ${w} — 2026`,d.headline||'Postseason')+E.postseasonBracket()+`<section class="section"><div class="wrap grid two"><div><div class="kicker">THE WEEKLY WRITE-UP</div><h2>${e(d.headline||`Week ${w}`)}</h2>${write}</div><div class="gotw"><div class="kicker">DECEMBER</div><h3>Win and keep moving.</h3><p>The championship bracket and Toilet Bowl field are driven by the final regular-season seeds.</p></div></div></section>`+sec('Weekly awards',`<div class="grid three">${aw}</div>`)}
  let ms=(d.matchups||[]).map(m=>E.renderMatchupCard(w,m[0],m[1])).join('')||'<div class="notice">Matchups pending.</div>';
  return hero(`Week ${w} — 2026`,d.headline||'Write-up pending')+liveBoardSection(w)+`<section class="section"><div class="wrap grid two"><div><div class="kicker">THE WEEKLY WRITE-UP</div><h2>${e(d.headline||'Pending')}</h2>${write}</div><div class="gotw"><div class="kicker">GAME OF THE WEEK</div><h3>${e(d.gameOfWeek||'To be selected')}</h3><p>${e(d.gotwCopy||'The marquee matchup will earn its spot.')}</p></div></div></section>`+matchupBreakdownSection(w,d)+predictionBoardSection(w)+sec('The slate',`<div class="matchup-pro-grid">${ms}</div>`,'Every matchup carries the old H2H receipts, latest archived meeting, biggest archived margin and current model edge.','MATCHUP FILES')+`<section class="section alt"><div class="wrap grid three">${card('Standings movement',e(d.standingsMovement||'Pending.'),'THE TABLE')}${card('Who smells trouble?',e(d.shameWatch||'Pending.'),'SHAME WATCH')}${card('Quote of the week',e(d.quote||'Pending.'),'GROUP CHAT')}</div></section>`+sec('Weekly awards',`<div class="grid three">${aw}</div>`)+`<section class="section"><div class="wrap"><div class="kicker">CURRENT POWER</div><h2>Our rankings</h2>${teamRankCards()}</div></section>`
}
function power(){let dyn=E.powerMetrics(),streak=E.streaks();let dynRows=dyn.map(t=>`<tr><td><b>${t.powerRank}</b></td><td>${E.badge(t.team,'xs')} <b>${e(t.team)}</b><div class="small">${e(t.manager)}</div></td><td>${t.w}-${t.l}</td><td>${t.gp?`${(t.pf/t.gp).toFixed(2)}`:'—'}</td><td>${e(streak[t.manager])}</td><td><b>${t.powerIndex.toFixed(1)}</b></td></tr>`).join('');let rows=(Y.powerRankings||Y.draftRankings).map(t=>`<tr><td><b>${t.rank}</b></td><td><b>${e(t.team)}</b><div class="small">${e(t.manager)}</div></td><td><span class="grade ${gradeClass(t.grade)}">${e(t.grade)}</span></td><td>${e(t.yahoo)}</td><td>${e(t.yahooProjection)}</td><td>${e(t.bestValue)}</td><td>${e(t.outlook)}</td></tr>`).join('');let cards=(Y.powerRankings||Y.draftRankings).map(t=>`<div class="card"><div class="rankline"><span class="rank-badge">#${t.rank}</span><span class="grade ${gradeClass(t.grade)}">${e(t.grade)}</span></div><div class="kicker">${e(t.manager)} · YAHOO ${e(t.yahoo)}</div><h3>${e(t.team)}</h3><p><b>The good:</b> ${e(t.best)}</p><p><b>The worry:</b> ${e(t.concern)}</p></div>`).join('');return hero('Power Rankings','The preseason scouting board stays on the record; the live power index moves with wins and scoring once games begin.')+sec('Live power index',`<div class="table-wrap"><table><thead><tr><th>#</th><th>Team</th><th>Record</th><th>PPG</th><th>Streak</th><th>Power</th></tr></thead><tbody>${dynRows}</tbody></table></div>`,'','CURRENT FORM')+sec('The preseason board',`<div class="table-wrap"><table><thead><tr><th>#</th><th>Team</th><th>Our grade</th><th>Yahoo</th><th>Yahoo projection</th><th>Best value</th><th>Verdict</th></tr></thead><tbody>${rows}</tbody></table></div>`,'','DRAFT-DAY RECEIPTS')+sec('Why we ranked them this way',`<div class="grid two">${cards}</div>`)}function odds(){let o=[...E.simulate()].sort((a,b)=>b.playoff-a.playoff);let bars=(field)=>o.map(x=>`<div class="odds-row"><strong>${e(x.team)}</strong><div class="bar"><span style="width:${Math.min(100,x[field]||0)}%"></span></div><b>${e(x[field]??0)}%</b></div>`).join('');let rows=o.map((x,i)=>`<tr><td>${i+1}</td><td>${E.badge(x.team,'xs')} <b>${e(x.team)}</b><div class="small">${e(x.manager)}</div></td><td>${x.playoff}%</td><td>${x.bye}%</td><td>${x.title}%</td><td>${x.toilet}%</td><td>${x.seedLow}–${x.seedHigh}</td><td>${x.avgSeed}</td></tr>`).join('');return hero('Playoff Odds','The Makers model reruns the 2026 schedule from the current standings and team strength every time the race changes.')+sec('Make the six-team bracket',bars('playoff'),'','PLAYOFF ODDS')+sec('First-round bye odds',bars('bye'),'','BYE EQUITY')+sec('Title equity',bars('title'),'','CHAMPIONSHIP ODDS')+sec('Toilet Bowl odds',bars('toilet'),'','SHAME RISK')+sec('Full model table',`<div class="table-wrap"><table><thead><tr><th>#</th><th>Team</th><th>Playoffs</th><th>Bye</th><th>Title equity</th><th>Toilet Bowl</th><th>Likely seed range</th><th>Avg seed</th></tr></thead><tbody>${rows}</tbody></table></div>`,'','EVERY NUMBER')}
function seasonMove(manager,year){if(year===2026){if(Y.transactionCounts2026&&Object.prototype.hasOwnProperty.call(Y.transactionCounts2026,manager))return Y.transactionCounts2026[manager];let s=Y.standings.find(x=>x.manager===manager);return s?s.moves:null}let season=D.seasons[String(year)];if(!season)return null;let r=season.standings.find(x=>x[1]===manager);return r?r[5]:null}
function activityCard(x){
  const type=String(x?.type||'MOVE').toUpperCase(),manager=x?.manager||x?.team||'League move',team=x?.team&&x.team!==manager?x.team:'',add=x?.add||'',drop=x?.drop||'',faab=x?.faab,time=x?.time||x?.date||'';
  const kind=/trade/.test(type.toLowerCase())?'trade':/waiver|claim/.test(type.toLowerCase())?'waiver':/drop/.test(type.toLowerCase())?'drop':'add';
  const fallback=String(x?.description||'Completed transaction').replace(/[\uE000-\uF8FF]/g,'').replace(/\s+/g,' ').trim();
  const players=[add?`<div class="activity-player activity-player-add"><span>ADD</span><strong>${e(add)}</strong></div>`:'',drop?`<div class="activity-player activity-player-drop"><span>DROP</span><strong>${e(drop)}</strong></div>`:''].join('');
  const detail=players||`<p class="activity-description">${e(fallback)}</p>`;
  const spend=faab!=null&&Number.isFinite(Number(faab))?`<span class="activity-faab">$${e(faab)} FAAB</span>`:'';
  const mark=kind==='trade'?'↔':kind==='drop'?'−':'+';
  return `<article class="activity-card activity-card-${kind}"><div class="activity-mark" aria-hidden="true">${mark}</div><div class="activity-main"><div class="activity-owner"><span class="activity-type">${e(type)}</span><strong>${e(manager)}</strong>${team?`<small>${e(team)}</small>`:''}</div><div class="activity-players">${detail}</div></div><div class="activity-meta">${spend}${time?`<time>${e(time)}</time>`:''}</div></article>`;
}
function activityTape(list,emptyCopy='Completed adds, drops, claims and trades will appear here.'){return Array.isArray(list)&&list.length?list.map(activityCard).join(''):`<div class="empty-state"><b>No 2026 transactions yet.</b><br>${e(emptyCopy)}</div>`}
function transactions(){
  let managers=D.records.map(r=>r.manager).filter(m=>m!=='El Rubio').concat(['El Rubio']).filter((x,i,a)=>a.indexOf(x)===i);
  let rows=managers.map(m=>{let vals=[2022,2023,2024,2025,2026].map(y=>seasonMove(m,y));let total=vals.reduce((sum,v)=>sum+(Number(v)||0),0);return `<tr><td><b>${e(m)}</b></td>${vals.map((v,i)=>`<td${i===4?' class="move-current"':''}>${i===4?`<b>${v==null?'—':e(v)}</b>`:(v==null?'—':e(v))}</td>`).join('')}<td class="move-total"><b>${total}</b></td></tr>`}).join('');
  const tape=activityTape(Y.recentTransactions||[],'The live tape is ready for completed adds, drops, claims and trades.');
  return hero('Moves & Trades','Historical churn plus the 2026 transaction tape.')+sec('2026 activity',`<div class="activity-feed" id="transaction-feed">${tape}</div>`,'','LIVE SEASON')+sec('Career move ledger',`<div class="table-wrap move-leaderboard-wrap" tabindex="0"><table class="move-leaderboard"><thead><tr><th>Manager</th><th>2022</th><th>2023</th><th>2024</th><th>2025</th><th class="move-current">2026</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table></div><div class="section-action"><a class="btn primary" href="waiver-wire.html">Open the 2026 Waiver Wire</a></div>`,'','THE CHURN')
}
function waiverAvailableSections(players=[]){
  const config=[['QB','Quarterbacks',15],['RB','Running Backs',25],['WR','Wide Receivers',25],['TE','Tight Ends',15],['K','Kickers',10],['DEF','Defenses',10]];
  const pool=Array.isArray(players)?players:[],week=Number(Y.week)||1,model=window.MAKERS_WAIVER_MODEL;
  if(!pool.length)return `<div class="table-wrap" tabindex="0"><table><tbody><tr><td><div class="empty-state"><b>Waiting for collector data.</b><br>Available players will populate after the next Makers Yahoo snapshot is imported.</div></td></tr></tbody></table></div>`;
  const nav=config.map(([pos])=>{const count=pool.filter(p=>String(p.position||p.pos||'').toUpperCase()===pos).length;return `<a href="#waiver-${pos.toLowerCase()}" class="waiver-position-pill"><b>${e(pos)}</b><span>${count}</span></a>`}).join('');
  const groups=config.map(([pos,label,target])=>{
    const list=pool.filter(p=>String(p.position||p.pos||'').toUpperCase()===pos).sort((a,b)=>{
      const ap=model?.projection?model.projection(a,week):Number(a.projected),bp=model?.projection?model.projection(b,week):Number(b.projected);
      const av=Number.isFinite(Number(ap))?Number(ap):-Infinity,bv=Number.isFinite(Number(bp))?Number(bp):-Infinity;
      return (bv-av)||String(a.name||'').localeCompare(String(b.name||''));
    }).slice(0,target);
    const rows=list.length?list.map((p,i)=>{
      const m=model?.metrics?model.metrics(p,week,i+1,list.length):{recent:week===1?'—':(p.recent??'—'),projected:p.projected??'—',faab:p.faabSuggestion||'—'};
      return `<tr><td><b>${e(p.name)}</b></td><td>${e(p.nflTeam||p.nfl||'')}</td><td>${e(m.recent)}</td><td class="waiver-projected"><b>${e(m.projected)}</b></td><td class="waiver-faab"><b>${e(m.faab)}</b></td></tr>`;
    }).join(''):`<tr><td colspan="5"><div class="empty-state">No ${e(label.toLowerCase())} captured.</div></td></tr>`;
    return `<section class="waiver-position-card" id="waiver-${pos.toLowerCase()}"><div class="waiver-position-head"><div><div class="kicker">${e(pos)}</div><h3>${e(label)}</h3></div><span class="waiver-position-count">${list.length} listed</span></div><div class="table-wrap waiver-position-table-wrap" tabindex="0"><table class="waiver-position-table"><thead><tr><th>Player</th><th>Team</th><th>Recent</th><th>Projected</th><th>Suggested FAAB</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
  }).join('');
  return `<nav class="waiver-position-nav" aria-label="Available player positions">${nav}</nav><div class="waiver-position-stack">${groups}</div>`;
}
function waiverContent(w){
  const faab=(w.faab||Y.faab||[]).sort((a,b)=>a.priority-b.priority).map(x=>`<tr><td><b>${e(x.priority)}</b></td><td>${e(x.manager)}</td><td>${e(x.team)}</td><td>$${e(x.spent)}</td><td><b>$${e(x.remaining)}</b></td><td>${e(x.claimsWon)}</td></tr>`).join('');
  const avail=waiverAvailableSections(w.topAvailable||Y.topAvailable||[]);
  const tx=activityTape(w.recentTransactions||Y.recentTransactions||[],'Completed adds, drops, claims and trades will land here as the season moves.');
  const status=w.apiStatus||Y.apiStatus||'Yahoo collector pending';
  return `<div class="live-status"><span class="status-dot ${/(connected|collector|updated)/i.test(status)?'on':'off'}"></span><div><b>${e(status)}</b><small>Last update: ${e(w.lastUpdated||Y.lastUpdated)}</small></div></div><div class="waiver-grid">${card('FAAB season','$100 per team. Spend wisely.','THE BUDGET')}${card('Privacy rule','Completed waiver activity and FAAB spent can be public. Pending bids stay private.','NO CHEATING')}</div><div class="waiver-section"><div class="section-head"><div><div class="kicker">MONEY LEFT TO BURN</div><h2>FAAB & waiver priority</h2></div></div><div class="table-wrap" tabindex="0"><table><thead><tr><th>Priority</th><th>Manager</th><th>Team</th><th>Spent</th><th>Remaining</th><th>Claims Won</th></tr></thead><tbody>${faab}</tbody></table></div></div><div class="waiver-section"><div class="section-head"><div><div class="kicker">WHO IS STILL OUT THERE?</div><h2>Available players by position</h2></div></div>${avail}</div><div class="waiver-section"><div class="section-head"><div><div class="kicker">THE TAPE</div><h2>League activity</h2></div></div><div class="activity-feed">${tx}</div></div>`;
}
function waivers(){return hero('Waiver Wire','FAAB, available players and completed league activity.')+`<section class="section"><div class="wrap"><div id="waiver-live-content">${waiverContent({})}</div></div></section>`}
async function refreshWaivers(){const cfg=window.MAKERS_API||{},url=cfg.waiverEndpoint;if(!url)return;try{let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);let data=await r.json();data.apiStatus=data.apiStatus||'Connected to Yahoo';data.lastUpdated=data.lastUpdated||new Date().toLocaleString();let el=document.getElementById('waiver-live-content');if(el)el.innerHTML=waiverContent(data)}catch(err){let b=document.querySelector('.live-status b');if(b)b.textContent='Yahoo connection temporarily unavailable'}}
function schedule(){const rank=Object.fromEntries((Y.draftRankings||[]).map(x=>[x.team,x.rank]));const mgr=t=>{let f=D.franchises.find(x=>x.current===t);return f?f.manager:t};const reg=(a,b)=>{let v=(D.regularSeasonH2H?.[a]||{})[b];return v?`${v[0]}-${v[1]}`:'0-0'};const games=[];for(let w=1;w<=14;w++){for(const [a,b] of (D.schedule2026[String(w)]||[]))games.push({w,a,b,ma:mgr(a),mb:mgr(b)})}const finalTags={'Andrew|TomD':'2022 FINAL REMATCH','Jim|Nick':'2023 FINAL REMATCH','Nate|Tommy':'2024 FINAL REMATCH','Adam|Andrew':'2025 FINAL REMATCH'};const key=(a,b)=>[a,b].sort().join('|');const tags=g=>{let z=[];if(finalTags[key(g.ma,g.mb)])z.push(finalTags[key(g.ma,g.mb)]);if((rank[g.a]||99)<=4&&(rank[g.b]||99)<=4)z.push('TOP-4 CLASH');let v=(D.regularSeasonH2H?.[g.ma]||{})[g.mb];if(v&&(v[0]+v[1]>=6)&&Math.abs(v[0]-v[1])<=1)z.push('RIVALRY');return z};let schedules=(Y.draftRankings||[]).map(t=>{let rows=[];let oppRanks=[];for(let w=1;w<=14;w++){let g=(D.schedule2026[String(w)]||[]).find(x=>x.includes(t.team));if(!g)continue;let opp=g[0]===t.team?g[1]:g[0],om=mgr(opp),tg=tags({w,a:t.team,b:opp,ma:t.manager,mb:om});oppRanks.push(rank[opp]||10);rows.push(`<a class="schedule-line${tg.length?' big':''}" href="${weekHref(w)}"><span class="schedule-week">W${w}</span><span class="schedule-opponent"><b>${e(opp)}</b><small>${e(om)} · REG H2H ${e(reg(t.manager,om))}</small></span><span class="schedule-tags">${tg.map(x=>`<em>${e(x)}</em>`).join('')}</span></a>`)}let avg=oppRanks.reduce((s,x)=>s+x,0)/(oppRanks.length||1);return `<article class="schedule-team-card"><div class="schedule-team-head"><div><div class="kicker">OUR POWER #${t.rank}</div><h3>${e(t.team)}</h3><p>${e(t.manager)} · Avg opponent power rank ${avg.toFixed(2)}</p></div></div>${rows.join('')}</article>`}).join('');let roads=(Y.draftRankings||[]).map(t=>{let rs=[];for(let w=1;w<=14;w++){let g=(D.schedule2026[String(w)]||[]).find(x=>x.includes(t.team));if(g){let opp=g[0]===t.team?g[1]:g[0];rs.push(rank[opp]||10)}}return {...t,avg:rs.reduce((a,b)=>a+b,0)/(rs.length||1)}}).sort((a,b)=>a.avg-b.avg);let familiar=[...games].sort((g1,g2)=>{let a=(D.regularSeasonH2H?.[g1.ma]?.[g1.mb]||[0,0]).reduce((x,y)=>x+y,0),b=(D.regularSeasonH2H?.[g2.ma]?.[g2.mb]||[0,0]).reduce((x,y)=>x+y,0);return b-a})[0];let wk1=[...games.filter(g=>g.w===1)].sort((a,b)=>(rank[a.a]+rank[a.b])-(rank[b.a]+rank[b.b]))[0];const importance=g=>tags(g).reduce((s,t)=>s+(t.includes('FINAL REMATCH')?100:t==='TOP-4 CLASH'?30:18),0)+Math.max(0,12-Math.abs((rank[g.a]||10)-(rank[g.b]||10))*2);const managers=[...new Set((Y.draftRankings||[]).map(x=>x.manager))],coverage=Object.fromEntries(managers.map(m=>[m,0])),pool=[...games],chosen=[];while(managers.some(m=>coverage[m]<2)&&pool.length){pool.sort((a,b)=>{const need=g=>(coverage[g.ma]<2?100:0)+(coverage[g.mb]<2?100:0);return (need(b)+importance(b))-(need(a)+importance(a))||a.w-b.w});const g=pool.shift();chosen.push(g);coverage[g.ma]=(coverage[g.ma]||0)+1;coverage[g.mb]=(coverage[g.mb]||0)+1}const remaining=pool.filter(g=>tags(g).length).sort((a,b)=>importance(b)-importance(a)||a.w-b.w);while(chosen.length<16&&remaining.length){const g=remaining.shift();if(chosen.some(x=>x.w===g.w&&key(x.a,x.b)===key(g.a,g.b)))continue;chosen.push(g);coverage[g.ma]=(coverage[g.ma]||0)+1;coverage[g.mb]=(coverage[g.mb]||0)+1}chosen.sort((a,b)=>a.w-b.w||importance(b)-importance(a));let marquee=chosen.map(g=>{const tg=tags(g),display=tg.length?tg:['MARQUEE'];return `<a class="marquee-game" href="${weekHref(g.w)}"><div><span>WEEK ${g.w}</span><b>${e(g.a)} vs ${e(g.b)}</b><small>${e(g.ma)} ${e(reg(g.ma,g.mb))} ${e(g.mb)} in the 2022–25 regular season</small></div><div>${display.map(x=>`<em>${e(x)}</em>`).join('')}</div></a>`}).join('');return hero('2026 Schedule','Fourteen regular-season weeks, organized by team with the old receipts attached.')+`<section class="section"><div class="wrap"><div class="section-head"><div><div class="kicker">SCHEDULE NOTABLES</div><h2>What jumps off the page</h2></div></div><div class="grid four">${card('Hardest road',`${e(roads[0].team)}<br><span class="small">${e(roads[0].manager)} · avg opponent rank ${roads[0].avg.toFixed(2)}</span>`,'SCHEDULE STRENGTH')}${card('Softest road',`${e(roads[roads.length-1].team)}<br><span class="small">${e(roads[roads.length-1].manager)} · avg opponent rank ${roads[roads.length-1].avg.toFixed(2)}</span>`,'SCHEDULE STRENGTH')}${card('Most familiar matchup',`${e(familiar.a)} vs ${e(familiar.b)}<br><span class="small">${e(familiar.ma)} ${e(reg(familiar.ma,familiar.mb))} ${e(familiar.mb)} regular season</span>`,'HISTORY')}${card('Week 1 heavyweight',`${e(wk1.a)} vs ${e(wk1.b)}<br><span class="small">Our preseason power #${rank[wk1.a]} vs #${rank[wk1.b]}</span>`,'OPENING WEEK')}</div></div></section>`+sec('Marquee dates',`<div class="marquee-list">${marquee}</div>`,'','CIRCLE THESE')+`<section class="section alt"><div class="wrap"><div class="section-head"><div><div class="kicker">TEAM-BY-TEAM</div><h2>Every road to Week 14</h2></div></div><div class="schedule-team-grid">${schedules}</div><div class="notice"><b>Weeks 15–17:</b> championship and consolation brackets are determined by the final regular-season standings.</div></div></section>`}function updatedRecords(){return E.careerRecords?E.careerRecords():D.records.map(r=>{let cur=Y.standings.find(s=>s.manager===r.manager);if(!cur)return {...r};let w=r.w+(cur.w||0),l=r.l+(cur.l||0),pf=r.pf+(cur.pf||0),pa=r.pa+(cur.pa||0),moves=r.moves+(cur.moves||0);return {...r,w,l,pf,pa,moves,pct:w/(w+l||1)}})}
