function franchises(){let all=updatedRecords();let rows=D.franchises.map(f=>{let r=all.find(x=>x.manager===f.manager)||historicalRecord(f.manager),t=ourTeam(f.manager),era=f.manager==='Billy'?'2025–PRESENT':f.manager==='El Rubio'?'2022–2024':'2022–PRESENT';return `<a class="card franchise" href="franchise.html?manager=${encodeURIComponent(f.manager)}"><div class="kicker">${e(f.manager)} · MODERN ERA ${e(era)}</div><h3>${e(f.current)}</h3><div class="stat">${r?`${r.w}-${r.l}`:'—'}</div><div class="small">${r?`${(r.pct*100).toFixed(1)}% · ${r.titles} titles · ${r.moves} moves`:''}</div><p class="franchise-blurb">${e(f.profile||f.note||'')}</p>${t?`<p><b>2026:</b> Our ${e(t.grade)} · draft rank #${t.rank}</p>`:''}</a>`}).join('');return hero('Franchise Files','The league dates to 2003. Complete franchise records run from 2022 forward; Billy and El Rubio remain separate histories.')+sec('Know your enemy',`<div class="grid two">${rows}</div>`,'','THE FRANCHISE LEDGER')}
function franchise(){
  let m=Q.get('manager')||'Andrew',f=currentFranchise(m),r=updatedRecords().find(x=>x.manager===m)||historicalRecord(m),t=ourTeam(m);
  if(!f)return hero('Franchise not found');
  let aliases=(f.aliases||[]).map(x=>`<li>${e(x)}</li>`).join(''),era=m==='Billy'?'2025–present':m==='El Rubio'?'2022–2024':'2022–present';
  let pow=E.powerMetrics().find(x=>x.manager===m),sim=E.simulate().find(x=>x.manager===m),stk=E.streaks()[m],sos=pow?E.remainingSOS(pow.team):null;
  let live=pow?sec('2026 command center',`<div class="grid four">${card('Current record',`${pow.w}-${pow.l}<br><span class="small">Seed #${pow.seed} · ${e(stk)}</span>`,'STANDINGS')}${card('Live power',`#${pow.powerRank} · ${pow.powerIndex.toFixed(1)}`,'POWER INDEX')}${card('Playoff picture',`${sim.playoff}% playoffs<br><span class="small">${sim.bye}% bye · ${sim.title}% title</span>`,'ODDS')}${card('Remaining road',`${sos==null?'—':sos.toFixed(2)} avg opp rank<br><span class="small">Seed range ${sim.seedLow}–${sim.seedHigh}</span>`,'SCHEDULE')}</div>`,'','RIGHT NOW'):'';
  let base=`<section class="section"><div class="wrap profile-top"><div class="profile-box"><div class="big-record">${r?`${r.w}-${r.l}`:'—'}</div><p>${r?`${(r.pct*100).toFixed(1)}% modern-era win rate · ${Number(r.pf).toFixed(2)} PF · ${r.moves} moves`:''}</p><p>${e(f.profile||'')}</p><ul>${aliases}</ul>${f.note?`<div class="notice">${e(f.note)}</div>`:''}</div>${t?`<div class="callout"><div class="kicker">2026 DRAFT RANK #${t.rank}</div><h3>${e(t.team)} · ${e(t.grade)}</h3><p>${e(t.outlook)}</p></div>`:''}</div></section>`;
  let outlook=t?sec('2026 outlook',`<div class="grid two">${card('The good',e(t.best))}${card('How it goes wrong',e(t.concern))}</div>`,'','OUR SCOUTING REPORT')+sec('Draft snapshot',`<div class="grid three">${card('Our grade',`<span class="grade ${gradeClass(t.grade)}">${e(t.grade)}</span>`)}${card('Yahoo grade',`<span class="grade ${gradeClass(t.yahoo)}">${e(t.yahoo)}</span>`)}${card('Best value',e(t.bestValue))}</div>`):'';
  const liveRoster=(Y.liveRosters||[]).find(x=>x.manager===m||x.team===f.current||x.team===t?.team);
  const roster=liveRoster&&liveRoster.players?.length?sec('Current Yahoo roster',`<div class="table-wrap franchise-roster-wrap" tabindex="0"><table class="franchise-roster-table"><thead><tr><th>Slot</th><th>Player</th><th>NFL</th><th>Pos</th><th>Status</th></tr></thead><tbody>${liveRoster.players.map(p=>`<tr><td><b>${e(p.slot||'—')}</b></td><td><b>${e(p.name||'')}</b></td><td>${e(p.nflTeam||'')}</td><td>${e(p.pos||p.position||'')}</td><td>${e(p.status||'—')}</td></tr>`).join('')}</tbody></table></div>`,`Yahoo roster snapshot · ${e(liveRoster.capturedAt||Y.lastUpdated||'')}`,'LIVE ROSTER'):'';
  return hero(`${m} — ${f.current}`,`Modern franchise history: ${era}. The league itself dates to 2003.`)+live+base+outlook+roster;
}
function warroom(){let ourRows=Y.draftRankings.map(t=>`<tr><td>${t.rank}</td><td>${E.badge(t.team,'xs')} <b>${e(t.team)}</b><div class="small">${e(t.manager)}</div></td><td><span class="grade ${gradeClass(t.grade)}">${e(t.grade)}</span></td><td>${e(t.yahoo)}</td><td>${e(t.bestValue)}</td></tr>`).join('');let yahoo=[...D.currentTeams].sort((a,b)=>b[4]-a[4]).map((r,i)=>`<tr><td>${i+1}</td><td><b>${e(r[0])}</b><div class="small">${e(r[1])}</div></td><td>${e(r[2])}</td><td>${e(r[3])}</td><td>${Number(r[4]).toFixed(2)}</td><td>$100</td><td>${e(D.waiverPriority2026[r[1]])}</td></tr>`).join('');let settings=Object.entries(D.settings2026||{}).map(([k,v])=>card(k,e(v))).join('');return hero('2026 War Room','The race, the schedule, the projections and the receipts — all in one place.')+E.renderWarRoomIntel()+E.postseasonBracket()+sec('Our draft-day field',`<div class="table-wrap"><table><thead><tr><th>#</th><th>Team</th><th>Our grade</th><th>Yahoo</th><th>Best value</th></tr></thead><tbody>${ourRows}</tbody></table></div>`,'','THE MAKERS VERDICT')+sec('Yahoo draft-day field',`<div class="table-wrap"><table><thead><tr><th>Power #</th><th>Team</th><th>Yahoo grade</th><th>Yahoo record</th><th>Power score</th><th>FAAB</th><th>Priority</th></tr></thead><tbody>${yahoo}</tbody></table></div>`,'','YAHOO SNAPSHOT')+sec('League setup',`<div class="grid three">${settings}</div>`)+`<section class="section alt"><div class="wrap"><div class="hero-actions"><a class="btn primary" href="schedule.html">Open Full Schedule</a><a class="btn ghost darkghost" href="drafts.html">Our Draft Breakdown</a><a class="btn ghost darkghost" href="weeks.html">Weekly Room</a></div></div></section>`}
